# Price or limit? Two doors to the same room (straight-line cost curve, illustrative)
# Each extra 1% cut below Reference costs $2 more per tonne: price = 2 x cut%
def cut_from_price(price):
    return min(price / 2, 100)

def price_from_cut(cut):
    return 2 * cut

print(f"Set a price of $50/t -> model finds a {cut_from_price(50):.0f}% cut")
print(f"Set a 60% cut       -> model finds a price of ${price_from_cut(60):.0f}/t")
print("Results to report: Policy minus Reference, not the policy run alone.")
